package com.jgeted.sagadyssey.social.needs;
import com.jgeted.sagadyssey.npc.brain.fieldwork.FieldworkStorage;
import com.jgeted.sagadyssey.worldsim.rights.*;
import com.jgeted.sagadyssey.worldsim.transfer.*;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.CompoundTag;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class SupplyFlowDataTest {
    private FieldworkStorage point(int x,SubjectRef owner){return new FieldworkStorage("minecraft:overworld",new BlockPos(x,1,0),UUID.randomUUID(),owner,AccessPolicy.PRIVATE,TransferIntent.DELIVERY,"test");}
    @Test void knowledgeIsActorLocalAndImmutable(){var d=new SupplyFlowData();var a=SubjectRef.character(UUID.randomUUID());var b=SubjectRef.character(UUID.randomUUID());var p=point(1,a);d.register(p);d.reveal(a,p.containerId());assertEquals(Set.of(p.containerId()),d.known(a));assertTrue(d.known(b).isEmpty());assertThrows(UnsupportedOperationException.class,()->d.known(a).clear());}
    @Test void exactRouteAndPendingPayloadRoundTrip(){var d=new SupplyFlowData();var a=SubjectRef.character(UUID.randomUUID());var source=point(1,a);var target=point(2,a);d.register(source);d.register(target);UUID need=UUID.randomUUID(),actor=UUID.randomUUID();d.demand(need,a,target.containerId());var p=new SupplyFlowData.Pending(UUID.randomUUID(),true,ContainerIds.npcCargo(actor),3,new ItemFingerprint("minecraft:coal",17),4,5,10);var route=new SupplyFlowData.Route(UUID.randomUUID(),need,source.containerId(),target.containerId(),a,3,actor,actor,SupplyFlowData.Stage.HELD,10,0,p,"pending");d.route(route);var restored=SupplyFlowData.load(d.save(new CompoundTag(),null),null);assertEquals(route,restored.route(route.id()));assertEquals(p.request(route),restored.route(route.id()).pending().request(route));}
    @Test void scopeAndEndpointIdentityCannotBeOverwritten(){var d=new SupplyFlowData();var a=SubjectRef.character(UUID.randomUUID());var source=point(1,a);var target=point(2,a);d.register(source);d.register(target);UUID id=UUID.randomUUID();d.demand(id,a,target.containerId());assertThrows(IllegalStateException.class,()->d.demand(id,a,source.containerId()));assertThrows(IllegalStateException.class,()->d.register(new FieldworkStorage(source.dimension(),source.position(),source.containerId(),SubjectRef.character(UUID.randomUUID()),source.policy(),source.intent(),source.authority())));}
    @Test void damagedOrOrphanedSupplyLedgerFailsClosed(){var tag=new SupplyFlowData().save(new CompoundTag(),null);tag.remove("Routes");assertThrows(IllegalArgumentException.class,()->SupplyFlowData.load(tag,null));assertThrows(IllegalArgumentException.class,()->new SupplyFlowData.Route(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),SubjectRef.character(UUID.randomUUID()),1,null,null,SupplyFlowData.Stage.CARRYING,0,0,null,"orphan"));}
    @Test void policiesCannotSilentlyChangeOrOverflow(){var d=new SupplyFlowData();var a=SubjectRef.household(UUID.randomUUID());var p=point(1,a);d.register(p);var policy=new SupplyFlowData.Policy("family",a,p.containerId(),new ItemFingerprint("minecraft:bread",0),6,"household");d.policy(policy);d.policy(policy);assertEquals(1,d.policies().size());assertThrows(IllegalStateException.class,()->d.policy(new SupplyFlowData.Policy("family",a,p.containerId(),policy.item(),7,"household")));assertEquals(policy,SupplyFlowData.load(d.save(new CompoundTag(),null),null).policies().getFirst());}
    @Test void merchantSchemaAndQuoteParametersAreStrict(){var tag=new MerchantSupplyData().save(new CompoundTag(),null);assertTrue(MerchantSupplyData.load(tag,null).journeys().isEmpty());tag.remove("Known");assertThrows(IllegalArgumentException.class,()->MerchantSupplyData.load(tag,null));assertThrows(IllegalArgumentException.class,()->new MerchantSupplyData.Offer(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),new ItemFingerprint("minecraft:coal",0),true,0,3,100));}
    @Test void sameQuantityRefreshDoesNotPostponeExternalRetry(){var d=new NeedRequestData();var key=new NeedRequest.Key(UUID.randomUUID(),"same",new ItemFingerprint("minecraft:coal",0),UUID.randomUUID(),0,1000);var r=d.openOrUpdate(key,3,3,10);d.transition(r.id(),NeedRequestStatus.WAITING_EXTERNAL,11,"no stock");assertEquals(11,d.openOrUpdate(key,3,3,100).updatedAt());}
}
